import React from 'react';
import { Line } from 'react-chartjs-2';
import {
    Chart as ChartJS,
    CategoryScale,
    LinearScale,
    PointElement,
    LineElement,
    Title,
    Tooltip,
    Legend,
} from 'chart.js';

ChartJS.register(
    CategoryScale,
    LinearScale,
    PointElement,
    LineElement,
    Title,
    Tooltip,
    Legend
);

const StockChart = ({ chartData, historicalIndicators }) => {
    // 1. Live Price Chart (per-minute)
    const livePriceData = {
        labels: chartData.labels,
        datasets: [
            {
                label: 'Live Stock Price',
                data: chartData.values,
                fill: false,
                borderColor: 'rgb(75, 192, 192)',
                backgroundColor: 'rgba(75, 192, 192, 0.5)',
                pointRadius: 1,
            },
        ],
    };

    const livePriceOptions = {
        responsive: true,
        interaction: {
            mode: 'index',
            intersect: false,
        },
        plugins: {
            title: {
                display: true,
                text: 'Live Price (1-Minute Updates)',
            },
        },
        scales: {
            y: {
                display: true,
                title: {
                    display: true,
                    text: 'Price',
                },
            },
        },
    };

    // 2. Historical Indicators Chart (daily)
    const indicatorDatasets = [];
    if (historicalIndicators) {
        // Daily Close Price
        indicatorDatasets.push({
            label: 'Daily Close Price',
            data: historicalIndicators.close,
            borderColor: 'rgb(75, 192, 192)',
            yAxisID: 'y',
            pointRadius: 0,
        });
        // RSI
        indicatorDatasets.push({
            label: 'RSI (14)',
            data: historicalIndicators.rsi,
            borderColor: 'rgb(255, 99, 132)',
            yAxisID: 'y1',
            pointRadius: 0,
        });
        // MACD
        indicatorDatasets.push({
            label: 'MACD',
            data: historicalIndicators.macd,
            borderColor: 'rgb(54, 162, 235)',
            yAxisID: 'y1',
            pointRadius: 0,
        });
        indicatorDatasets.push({
            label: 'MACD Signal',
            data: historicalIndicators.macds,
            borderColor: 'rgb(255, 206, 86)',
            yAxisID: 'y1',
            pointRadius: 0,
        });
        // Bollinger Bands
        indicatorDatasets.push({
            label: 'Bollinger Upper',
            data: historicalIndicators.bb_upper,
            borderColor: 'rgb(153, 102, 255, 0.5)',
            yAxisID: 'y',
            pointRadius: 0,
        });
        indicatorDatasets.push({
            label: 'Bollinger Middle',
            data: historicalIndicators.bb_middle,
            borderColor: 'rgb(201, 203, 207)',
            yAxisID: 'y',
            pointRadius: 0,
        });
        indicatorDatasets.push({
            label: 'Bollinger Lower',
            data: historicalIndicators.bb_lower,
            borderColor: 'rgb(153, 102, 255, 0.5)',
            yAxisID: 'y',
            pointRadius: 0,
        });
        // Stochastic Oscillator
        indicatorDatasets.push({
            label: 'Stochastic %K',
            data: historicalIndicators.stoch_k,
            borderColor: 'rgb(0, 255, 0)',
            yAxisID: 'y1',
            pointRadius: 0,
        });
        indicatorDatasets.push({
            label: 'Stochastic %D',
            data: historicalIndicators.stoch_d,
            borderColor: 'rgb(255, 165, 0)',
            yAxisID: 'y1',
            pointRadius: 0,
        });
    }

    const indicatorData = {
        labels: historicalIndicators ? historicalIndicators.labels : [],
        datasets: indicatorDatasets,
    };

    const indicatorOptions = {
        responsive: true,
        interaction: {
            mode: 'index',
            intersect: false,
        },
        plugins: {
            title: {
                display: true,
                text: 'Historical Indicators (1-Year Daily)',
            },
        },
        scales: {
            y: {
                type: 'linear',
                display: true,
                position: 'left',
                title: {
                    display: true,
                    text: 'Price',
                },
            },
            y1: {
                type: 'linear',
                display: true,
                position: 'right',
                grid: {
                    drawOnChartArea: false,
                },
                title: {
                    display: true,
                    text: 'Indicator Value',
                },
                min: 0,
                max: 100,
            },
        },
    };

    return (
        <div>
            <div style={{ marginBottom: '40px' }}>
                <Line data={livePriceData} options={livePriceOptions} />
            </div>
            {historicalIndicators && (
                <div>
                    <Line data={indicatorData} options={indicatorOptions} />
                </div>
            )}
        </div>
    );
};

export default StockChart;
